import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename

app = Flask(__name__)
UPLOAD_DIR = '/tmp/uploads'
REPORT_DIR = '/tmp/reports'

os.makedirs(UPLOAD_DIR, exist_ok=True)
os.makedirs(REPORT_DIR, exist_ok=True)

ALLOWED_EXTENSIONS = {'csv', 'txt', 'json', 'xml'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def validate_content_length(data):
    if len(data) > 10 * 1024 * 1024:  # 10MB limit
        return False
    return True

@app.route('/api/convert', methods=['POST'])
def convert_file():
    """Convert uploaded file to PDF using system pandoc"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    f = request.files['file']
    if f.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(f.filename):
        return jsonify({'error': 'File type not allowed'}), 403

    filename = secure_filename(f.filename)
    input_path = os.path.join(UPLOAD_DIR, filename)
    f.save(input_path)

    # Validate file size after save
    if os.path.getsize(input_path) > 10 * 1024 * 1024:
        os.unlink(input_path)
        return jsonify({'error': 'File too large'}), 413

    output_name = os.path.splitext(filename)[0] + '.pdf'
    output_path = os.path.join(REPORT_DIR, output_name)

    # Build conversion command
    fmt = request.args.get('format', 'markdown')
    extra_args = request.args.get('args', '')

    cmd = f'pandoc -f {fmt} -t pdf -o {output_path} {input_path} {extra_args}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=REPORT_DIR
        )
        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        return send_file(output_path, as_attachment=True, download_name=output_name)
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup
        if os.path.exists(input_path):
            os.unlink(input_path)
        if os.path.exists(output_path):
            os.unlink(output_path)

@app.route('/api/preview', methods=['POST'])
def preview_file():
    """Generate text preview of uploaded file"""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    f = request.files['file']
    if not allowed_file(f.filename):
        return jsonify({'error': 'File type not allowed'}), 403

    content = f.read(4096).decode('utf-8', errors='replace')
    # Basic XSS prevention for preview
    content = content.replace('<', '&lt;').replace('>', '&gt;')
    return jsonify({'preview': content, 'truncated': f.read(1) != b''})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
